{"name":"SetAirConditionerCoolModeThenAutoAfter30Minutes","cron":"","period":0,"code":"prev := (#AirConditioner).airconditioner_mode
curr = (#AirConditioner).airconditioner_mode
if (prev != "cool" and curr == "cool") {
    (#AirConditioner).airconditioner_setairconditionermode("auto")
}
delay(30 MIN)
prev := (#AirConditioner).airconditioner_mode
curr = (#AirConditioner).airconditioner_mode
if (prev != "auto" and curr == "auto") {
    (#AirConditioner).airconditioner_setairconditionermode("cool")
}
prev = curr"}

{"name":"AdjustAirConditionerBasedOnTemperature","cron":"","period":0,"code":"prevTemp := (#TemperatureSensor).temperaturesensor_temperature
currTemp := (#TemperatureSensor).temperaturesensor_temperature
if (prevTemp < 20 and currTemp >= 20 and currTemp < 30) {
    (#AirConditioner).airconditioner_setairconditionermode("auto")
} else if (currTemp >= 30) {
    (#AirConditioner).airconditioner_setairconditionermode("cool")
}
prevTemp = currTemp"}

